// Generated by the PSX import (tools/import_psx.py + this file's generator in POLISH_NOTES 151): the owner's packs, one maker per piece.
import { THREE, pxMat, fbxPiece, fbxWhole, glbRig, objTool } from './psx_kit.js';
import { mat } from './kit.js';
// Street Furniture 1: props (sizes set to real ones; the files mix centimetres and metres).
export const makePxBarrel = () => fbxWhole('px_st_barrel', { '*': pxMat('px_st_barrel', { double: true }) }, { height: 0.88 });
export const makePxBottles = () => fbxWhole('px_st_bottles', { '*': pxMat('px_st_bottles', { double: true }) }, { largest: 0.32 });
export const makePxWoodCrate = () => fbxWhole('px_st_box', { '*': pxMat('px_st_box', { double: true }) }, { largest: 0.6 });
export const makePxAirConditioner = () => fbxWhole('px_st_conditioner', { '*': pxMat('px_st_conditioner', { double: true }) }, { largest: 0.85 });
export const makePxCrowbar = () => fbxWhole('px_st_crowbar', { '*': pxMat('px_st_crowbar', { double: true }) }, { largest: 0.75 });
export const makePxFlashlight = () => fbxWhole('px_st_flashlight', { '*': pxMat('px_st_flashlight', { double: true }) }, { largest: 0.25 });
export const makePxFloppyDisk = () => fbxWhole('px_st_floppy', { '*': pxMat('px_st_floppy', { double: true }) }, { largest: 0.09 });
export const makePxGarbageBag = () => fbxWhole('px_st_garbagebag', { '*': pxMat('px_st_garbagebag', { double: true }) }, { height: 0.7 });
export const makePxGasMask = () => fbxWhole('px_st_gasmask', { '*': pxMat('px_st_gasmask', { double: true }) }, { largest: 0.3 });
export const makePxHammer = () => fbxWhole('px_st_hammer', { '*': pxMat('px_st_hammer', { double: true }) }, { largest: 0.33 });
export const makePxOldLock = () => fbxWhole('px_st_oldlock', { '*': pxMat('px_st_oldlock', { double: true }) }, { largest: 0.09 });
export const makePxDumpster = () => fbxWhole('px_st_trashcan', { '*': pxMat('px_st_trashcan', { double: true }) }, { largest: 1.9 });
// the owner's tools pack (Axe01 / Pickaxe01 OBJ): its texture (AxePickaxe01_a.jpg) did not come with the files, so for now
// the head is scratched steel and the handle oak from the library
const steel = () => mat('g132_metal_scratched', { tint: '#c8ccd0', rough: 0.45, metal: 0.6 }), oak = () => mat('laminate_oak', { rough: 0.7 });
export const makePxAxe = () => objTool('px_tl_axe01', steel(), oak(), { largest: 0.75 });
export const makePxPickaxe = () => objTool('px_tl_pickaxe01', steel(), oak(), { largest: 0.9 });
